using System.Net.Http.Json; using System.Text.Json.Serialization; using AeC.Application.DTOs; using AeC.Application.Interfaces; using AeC.Shared.Extensions; using Microsoft.Extensions.Logging;
namespace AeC.Infrastructure.Services;
public sealed class ViaCepService(HttpClient http, ILogger<ViaCepService> logger) : IViaCepService
{ public async Task<ViaCepAddressDto?> BuscarAsync(string cep,CancellationToken ct=default){ var clean=cep.OnlyDigits(); if(clean.Length!=8) return null; try{ var r=await http.GetFromJsonAsync<ViaCepResponse>($"{clean}/json/",ct); return r is null||r.Erro ? null : new(r.Cep??clean,r.Logradouro??"",r.Complemento,r.Bairro??"",r.Localidade??"",r.Uf??""); } catch(Exception ex){ logger.LogWarning(ex,"Falha ao consultar ViaCEP {Cep}",clean); return null; } } sealed class ViaCepResponse{ public string? Cep{get;set;} public string? Logradouro{get;set;} public string? Complemento{get;set;} public string? Bairro{get;set;} public string? Localidade{get;set;} public string? Uf{get;set;} [JsonPropertyName("erro")] public bool Erro{get;set;} } }
